  private val palettes = mapOf(
    "death-star" to intArrayOf(0xB6B8BC, 0x8C8F95, 0x47484C, 0xE5E5E7, 0x5CF59A),
    "claude" to intArrayOf(0xEBAB97, 0xD97757, 0x713B2A, 0xF9E1D9, 0x5CF59A),
    "codex" to intArrayOf(0xA9DFC3, 0x6FCBA0, 0x376952, 0xE1F4EA, 0x5CF59A),
    "opencode" to intArrayOf(0xF1C0D8, 0xE59AC1, 0x784E64, 0xFBE9F1, 0x5CF59A),
  )
  private val neutral = intArrayOf(0xBFC1C6, 0x9A9CA4, 0x4E5054, 0xE8E8EA, 0x5CF59A)

  fun draw(celestials: List<String>): Bitmap {
    val shown = celestials.ifEmpty { listOf("/ringed") }.take(3)
    val bitmap = Bitmap.createBitmap(96, 96, Bitmap.Config.ARGB_8888)
    val canvas = Canvas(bitmap)
    val paint = Paint()
    val size = if (shown.size == 1) 64f else 32f
    val left = (96f - shown.size * size) / 2
    shown.forEachIndexed { index, celestial ->
      val parts = celestial.split("/", limit = 2)
      val body = parts.getOrElse(1) { "ringed" }
      val runs = bodies[body] ?: bodies.getValue("ringed")
      val tones = palettes[body] ?: palettes[parts[0]] ?: neutral
      val unit = size / 16
      for (at in runs.indices step 4) {
        paint.color = tones[runs[at + 3]] or 0xff000000.toInt()
        val x = left + index * size + runs[at] * unit
        val y = (96 - size) / 2 + runs[at + 1] * unit
        canvas.drawRect(x, y, x + runs[at + 2] * unit, y + unit, paint)
      }
    }
    return bitmap
  }
